//! The plugin-owned upstream configuration contract for chat_router.
//! The schema is captured from the verified threetched binary at every seal
//! through the threetched plugin's pinned capture; nothing is imported or
//! stored here. All section/method schemas derive from that one capture.
use serde_json::{Map, Value};
use std::collections::BTreeSet;

pub fn document() -> &'static Value {
    super::threetched::config_schema()
        .expect("threetched config schema must be captured from the binary at seal")
}

fn references(node: &Value, out: &mut BTreeSet<String>) {
    match node {
        Value::Object(map) => {
            if let Some(name) = map
                .get("$ref")
                .and_then(Value::as_str)
                .and_then(|r| r.strip_prefix("#/$defs/"))
            {
                out.insert(name.to_string());
            }
            for child in map.values() {
                references(child, out);
            }
        }
        Value::Array(items) => {
            for child in items {
                references(child, out);
            }
        }
        _ => {}
    }
}

/// Derive a self-contained section from the plugin contract, retaining transitive definitions.
pub fn section_from(document: &Value, key: &str) -> Value {
    let property = &document["properties"][key];
    let mut section = property
        .as_object()
        .expect("config property is an object")
        .clone();
    let definitions = document["$defs"]
        .as_object()
        .expect("config contract has definitions");
    let mut pending = BTreeSet::new();
    let mut included = Map::new();
    references(property, &mut pending);
    while let Some(name) = pending.pop_first() {
        if included.contains_key(&name) {
            continue;
        }
        let definition = definitions.get(&name).expect("config reference resolves");
        references(definition, &mut pending);
        included.insert(name, definition.clone());
    }
    if !included.is_empty() {
        section.insert("$defs".into(), Value::Object(included));
    }
    Value::Object(section)
}

pub fn section(key: &str) -> Value {
    section_from(document(), key)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn derived_section_keeps_recursive_dependencies_without_unrelated_definitions() {
        let contract = serde_json::json!({
            "properties": {"network": {"$ref": "#/$defs/Network"}},
            "$defs": {
                "Network": {"type": "object", "properties": {"peer": {"$ref": "#/$defs/Peer"}}},
                "Peer": {"type": "object", "properties": {"network": {"$ref": "#/$defs/Network"}}},
                "Unrelated": {"type": "string"}
            }
        });
        let section = section_from(&contract, "network");
        assert_eq!(section["$defs"].as_object().unwrap().len(), 2);
        assert_eq!(section["$ref"], "#/$defs/Network");
        jsonschema::validator_for(&section).expect("recursive section is self-contained");
    }

    #[test]
    fn every_plugin_section_is_self_contained_and_validates_without_external_files() {
        let contract = document();
        jsonschema::validator_for(contract).expect("full contract compiles");
        for key in contract["properties"].as_object().unwrap().keys() {
            jsonschema::validator_for(&section(key))
                .unwrap_or_else(|error| panic!("section {key}: {error}"));
        }
    }
}

//! Chat response plugin (OD-90 stage 1).
//!
//! Every chat turn ends in a response tool call, never raw model text. The
//! three response methods are those tool calls; this plugin IS their schema.
//!
//! Owner decisions (2026-09-28): a conversation belongs to the asking human's
//! principal and spans logins. Each committed turn records the session it came
//! from as provenance. An agent identity (the chain actor) authors responses
//! into the human's private scope, bound by a bridge-minted `turn_id`. Turns
//! form a per-conversation sub-chain whose order and completeness can be
//! verified from public fields alone (`conversation_id`, `turn_index`,
//! `prev_turn_hash`, `turn_hash`, `content_hash`), without reading content.
//!
//! Content fields carry `x-opdbus-private: true` (OD-91 marker). This plugin
//! only declares the marker; the chain and vector filters that honour it are
//! OD-91's work.

use anyhow::Result;
use async_trait::async_trait;
use op_state::{ApplyResult, Checkpoint, PluginCapabilities, StateDiff, StatePlugin};
use op_state_store::PluginSchema;
use serde::{Deserialize, Serialize};
use simd_json::OwnedValue as Value;
use std::collections::BTreeMap;

pub const PLUGIN_ID: &str = "chat_response";
pub const PLUGIN_VERSION: &str = "1.0.0";
/// Agents only: authors the three response methods into a human's scope.
pub const RESPOND_CAPABILITY: &str = "chat_response.respond";
/// Humans, on their own principal scope: start a conversation and read it.
pub const READ_CAPABILITY: &str = "chat_response.read";

/// Humans, on their own principal scope: submit one message turn.
/// Grants: submit_turn — the door's chat operation admits it, the bridge
/// opens the answer turn for the designated responder.
pub const SUBMIT_CAPABILITY: &str = "chat_response.submit";
/// Content-free commit announcement (owner key, ids and hashes only).
pub const RESPONSE_COMMITTED_SIGNAL: &str = "response_committed";

// ── Response content (private) ───────────────────────────────────────────────

/// How the user interface presents a `respond_to_user` message.
#[derive(Debug, Clone, Copy, Serialize, Deserialize, schemars::JsonSchema, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
pub enum MessageType {
    Success,
    Info,
    Warning,
    Error,
}

/// Why a request cannot be performed.
#[derive(Debug, Clone, Copy, Serialize, Deserialize, schemars::JsonSchema, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
pub enum RefusalCategory {
    Dangerous,
    NotAllowed,
    MissingInfo,
    PolicyViolation,
    NotSupported,
}

/// The authored content of one response. `content_hash` is the SHA-256 of
/// this value's canonical JSON (object keys sorted), so it commits to the
/// content without revealing it.
#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema, PartialEq)]
#[serde(tag = "kind", rename_all = "snake_case", deny_unknown_fields)]
pub enum ResponseContent {
    /// `respond_to_user`: the answer, optionally with a validated Canvas.
    UserResponse {
        #[schemars(
            description = "The message shown to the user [PII]",
            extend("x-opdbus-private" = true)
        )]
        message: String,
        #[schemars(description = "How the message is presented")]
        message_type: MessageType,
        #[serde(default)]
        #[schemars(description = "Tool or method names the agent called to produce this response")]
        related_actions: Vec<String>,
        #[serde(default)]
        #[schemars(
            description = "json-render Canvas spec validated against the sealed json_render Canvas profile [PII]",
            extend("x-opdbus-private" = true)
        )]
        canvas: Option<serde_json::Map<String, serde_json::Value>>,
    },
    /// `request_clarification`: the agent needs more from the user.
    Clarification {
        #[schemars(
